// Helper methods to count parentheses
method CountOpen(s: string, start: int, end: int) returns (count: int)
    requires 0 <= start <= end <= |s|
    ensures count >= 0
{
    count := 0;
    var i := start;
    while i < end
        invariant start <= i <= end
        invariant count >= 0
    {
        if s[i] == '(' {
            count := count + 1;
        }
        i := i + 1;
    }
}

method CountClose(s: string, start: int, end: int) returns (count: int)
    requires 0 <= start <= end <= |s|
    ensures count >= 0
{
    count := 0;
    var i := start;
    while i < end
        invariant start <= i <= end
        invariant count >= 0
    {
        if s[i] == ')' {
            count := count + 1;
        }
        i := i + 1;
    }
}
